+import { pool } from "./pool.ts";
+
+export interface JobEvent {
+  id: string;
+  jobId: string;
+  payload: string;
+  consumed: boolean;
+  createdAt: string;
+}
+
+export const publishJobEvent = async (
+  jobId: string,
+  payload: string,
+): Promise<void> => {
+  await pool.query(
+    `INSERT INTO job_events (job_id, payload, consumed)
+     VALUES ($1, $2, false)`,
+    [jobId, payload],
+  );
+};
+
+export const getUnconsumedEvents = async (
+  limit: number = 10,
+): Promise<JobEvent[]> => {
+  const result = await pool.query(
+    `SELECT id, job_id as "jobId", payload, consumed, created_at as "createdAt"
+     FROM job_events
+     WHERE consumed = false
+     ORDER BY created_at ASC
+     LIMIT $1`,
+    [limit],
+  );
+  return result.rows;
+};
+
+export const markEventConsumed = async (eventId: string): Promise<void> => {
+  await pool.query("UPDATE job_events SET consumed = true WHERE id = $1", [
+    eventId,
+  ]);
+};
+
+export const markEventsConsumed = async (eventIds: string[]): Promise<void> => {
+  if (eventIds.length === 0) return;
+  const placeholders = eventIds.map((_, i) => `$${i + 1}`).join(",");
+  await pool.query(
+    `UPDATE job_events SET consumed = true WHERE id IN (${placeholders})`,
+    eventIds,
+  );
+};
