+import { createServer, IncomingMessage, ServerResponse } from "http";
+import { getUnconsumedEvents, markEventsConsumed } from "./events.ts";
+
+const PORT = process.env.PORT || 3000;
+
+interface RequestContext {
+  method: string;
+  pathname: string;
+  searchParams: URLSearchParams;
+}
+
+const parseRequest = (req: IncomingMessage): RequestContext => {
+  const url = new URL(req.url || "", `http://${req.headers.host}`);
+  return {
+    method: req.method || "GET",
+    pathname: url.pathname,
+    searchParams: url.searchParams,
+  };
+};
+
+const sendJson = (
+  res: ServerResponse,
+  statusCode: number,
+  data: unknown,
+): void => {
+  res.writeHead(statusCode, { "Content-Type": "application/json" });
+  res.end(JSON.stringify(data));
+};
+
+export const startServer = (): void => {
+  const server = createServer(async (req, res) => {
+    try {
+      const ctx = parseRequest(req);
+
+      // GET /api/job-events - Retrieve unconsumed job events
+      if (ctx.pathname === "/api/job-events" && ctx.method === "GET") {
+        const limit = parseInt(ctx.searchParams.get("limit") || "10", 10);
+        const events = await getUnconsumedEvents(Math.min(limit, 100));
+        return sendJson(res, 200, { events });
+      }
+
+      // POST /api/job-events/consume - Mark events as consumed
+      if (ctx.pathname === "/api/job-events/consume" && ctx.method === "POST") {
+        let body = "";
+        req.on("data", (chunk) => {
+          body += chunk;
+        });
+        req.on("end", async () => {
+          try {
+            const { eventIds } = JSON.parse(body);
+            if (!Array.isArray(eventIds)) {
+              return sendJson(res, 400, {
+                error: "eventIds must be an array",
+              });
+            }
+            await markEventsConsumed(eventIds);
+            return sendJson(res, 200, { consumed: eventIds.length });
+          } catch (err) {
+            return sendJson(res, 400, { error: "Invalid request body" });
+          }
+        });
+        return;
+      }
+
+      // Health check
+      if (ctx.pathname === "/health" && ctx.method === "GET") {
+        return sendJson(res, 200, { status: "ok" });
+      }
+
+      sendJson(res, 404, { error: "Not found" });
+    } catch (err) {
+      console.error("Request error:", err);
+      sendJson(res, 500, { error: "Internal server error" });
+    }
+  });
+
+  server.listen(PORT, () => {
+    console.log(`Job events server listening on port ${PORT}`);
+  });
+};
